class Solution {
    public int longestBeautifulSubstring(String word) {
        int ans = 0, currLen = 1, vowelCount = 1;
        for (int i = 1; i < word.length(); ++i) {
            if (word.charAt(i) >= word.charAt(i - 1)) {
                currLen++;
                if (word.charAt(i) > word.charAt(i - 1)) vowelCount++;
            } else {
                currLen = 1;
                vowelCount = 1;
            }
            if (vowelCount == 5) {
                ans = Math.max(ans, currLen);
            }
        }
        return ans;
    }
}

