    let ans = 0, currLen = 1, vowelCount = 1;
    for (let i = 1; i < word.length; ++i) {
        if (word[i] >= word[i - 1]) {
            currLen++;
            if (word[i] > word[i - 1]) vowelCount++;
        } else {
            currLen = 1;
            vowelCount = 1;
        }
        if (vowelCount === 5) {
            ans = Math.max(ans, currLen);
